const API_URL = 'https://jsonplaceholder.typicode.com'

type FetchOptions = RequestInit & { next?: { revalidate?: number | false } }

async function fetchJson<T>(path: string, init?: FetchOptions): Promise<T> {
  const res = await fetch(`${API_URL}${path}`, init)
  if (!res.ok) {
    throw new Error(`Request to ${path} failed with status ${res.status}`)
  }
  return res.json() as Promise<T>
}

export function getPosts(init?: FetchOptions): Promise<Post[]> {
  return fetchJson<Post[]>('/posts', init)
}

export function getRecentPosts(limit: number): Promise<Post[]> {
  // Equivalent of getServerSideProps: never cache, fetch on every request.
  return fetchJson<Post[]>(`/posts?_limit=${limit}`, { cache: 'no-store' })
}

/** Returns `null` when the post does not exist. */
export async function getPost(
  id: string,
  revalidate: number
): Promise<Post | null> {
  const res = await fetch(`${API_URL}/posts/${encodeURIComponent(id)}`, {
    next: { revalidate },
  })
  if (res.status === 404) return null
  if (!res.ok) {
    throw new Error(`Request for post ${id} failed with status ${res.status}`)
  }
  return res.json() as Promise<Post>
}

export function getComments(id: string, revalidate: number): Promise<Comment[]> {
  return fetchJson<Comment[]>(`/posts/${encodeURIComponent(id)}/comments`, {
    next: { revalidate },
  })
